   "essay": {
    "head": "四、论述题",
    "desc": "本大题共2小题，每小题13分，共26分。",
    "score": 13,
    "items": [
     {
      "q": "论述：试论《西厢记》的戏剧冲突。",
      "a": "（1）《西厢记》的戏剧冲突有两条线索：一是以老夫人及郑恒为一方，以崔莺莺、张生、红\n娘为另一方的冲突；二是崔莺莺、张生、红娘之间的矛盾冲突。前者是主线，后者是辅线，\n两条线索互相制约，交错展开。（6 分）\n（2）孙飞虎兵围普救寺之后，崔、张与老夫人的冲突表面化。（2 分）\n（3）“拷红”是戏剧冲突的又一大转折，人物之间的冲突已经明显表现为两种婚姻观念的冲\n突。（4 分）\n（4）郑恒阻挠失败，故事以大团圆结局。从根本意义上说，戏剧的矛盾冲突并不是以崔、\n张一方的绝对胜利而结束的，而是一种妥协的结果。（2 分）",
      "e": ""
     },
     {
      "q": "论述：试以具体作品为例，论述“三言”的艺术特色。",
      "a": "（1）随着表现领域的拓展，“三言”中的小说更加贴近日常的世俗生活，善于在日常生活中\n抓住一些巧合来构成富有传奇色彩的故事，使小说的情节曲折跌宕，引人入胜。（5 分）\n（2）“三言”继承了宋元话本以情节展开和人物行动表现人物性格的写法，把人物置于与外\n部世界的激烈冲突中来显示其内心矛盾，或者通过一系列行动反复感染人物性格，在表现人\n物内心活动方面比较细致。（5 分）\n（3）与宋元话本以俗为尚的语言相比，“三言”的语言经过冯梦龙的加工润色，更加精炼，\n更能体现出雅俗共赏的特征。（4 分）",
      "e": ""
     }
    ]
   }
