      "q": "名词解释：台阁体",
      "a": "台阁体：\n答案：“台阁”又称“馆阁”，主要指翰林院和内阁。“台阁体”是当时台阁名臣、史称“三\n杨”的杨士奇、杨荣、杨溥所代表的诗文风格。他们的作品用于歌功颂德、应酬交际，追求\n雍容醇厚、平正典雅，缺乏个性风采，效仿者更是陈陈相因，千篇一律，无艺术生命可言。。",
