    "items": [
     {
      "q": "论述：试论杨万里“诚斋体”诗歌的艺术特色。",
      "a": "（1）以日常生活中的小情趣为题，写得活泼自然，风趣诙谐。（3 分）\n（2）想象新奇，语言通俗明快，风格流转圆活。（3 分）\n（3）以绝句最为出色，学习借鉴王安石的半山体和唐人晚唐体，学习晚唐体的空灵轻快，\n改变宋诗以人文景观为主的习惯，以自然意象为主，着重表现的是山水景观所蕴涵的自然灵\n性和知觉情意，活泼而充满奇趣，被认为是真正的“活法”诗。（5 分）\n（4）背离江西诗派诗法，变深刻为浅近，理趣减少，生活情趣增加，状物写情无不入妙。\n（3 分）",
      "e": ""
     },
     {
      "q": "论述：试述《红楼梦》人物形象塑造的成就。",
      "a": "（1）塑造了上百个不同身份、不同个性的人物，无不传神，各具光彩。（6 分）\n（2）善于写出人物的不同性格，更能将同一阶层或同一类人物对比写照，写出各自不同的\n性格特征。（4 分）\n（3）能将人物置于广阔的社会环境中，从各个层面反复渲染，写出人物的复杂性，达到了\n典型化的艺术高度。（4 分）",
      "e": ""
     }
    ]
