      "q": "名词解释：西昆体",
      "a": "西昆体：\n答案：西昆体之所以成为一个诗歌流派是以《西昆酬唱集》的编纂为标志的。此集的作者有\n17 人，共收诗250 首，杨亿、钱惟演、刘筠是主要的作家。西昆体的创作特色是学李商隐\n的近体律诗，讲究声律文采，修辞重用典。其长处是文辞密丽，气象典雅，扫五代之衰飒，\n创造纯宋之诗歌；短处是太雕琢而无自然态度，太堆砌而少意味。而西昆体的最主要特色还\n是讲究修辞。",
