      "a": "试从杜丽娘的形象塑造看《牡丹亭》的思想与社会意义\n答案：\n(1)《牡丹亭》成功塑造了杜丽娘这一追求自由与爱情的女性形象。她处在一个深受理学影\n响、压抑自由人性的生活氛围里,但并未泯灭自然人性。(2 分)(2)杜丽娘因感春而入梦,与 柳梦梅梦中相会为情而死,是杜丽娘性格的一次升华(3分)(3)她身为鬼魂,仍对柳梦梅一往\n情深,敢向阎王殿下的胡判官诉说感梦而亡的经过,在历尽险阻之后,终与柳梦梅在现实中结\n合为情再生,是杜丽娘性格的又一次升华。(3 分)(4)回到现实之后,杜丽娘敢于在朝堂之上\n对抗父命,向皇帝诉说心曲,堪称其性格的第三次升华。(3 分)(5)小说通过杜丽娘形象的塑\n造,张扬至情,肯定自然人性,肯定情与欲的完美结合,对于提倡贞洁纲常的传统道德观念以\n猛烈的冲击,具有鲜明的时代精神。(3 分)",
