      "a": "（1）《儒林外史》全书存在两大对立的形象体系：一类是以牺牲自我与个性为代价、追求功名富贵的利禄之徒（4分）；一类是保持独立人格、讲究文行出处的潇洒士人。二者势若水火，泾渭分明（4分）。\n（2）第一类人物主要以范进、周进、鲁编修等为代表，他们为了功名利禄，丑态毕露，人格沦丧。第二类人物主要以王冕、杜少卿等为代表，他们追慕前贤，崇尚魏晋名士风度，在这些人物身上，寄托了作者的人格理想。（3分）\n（3）两组形象体系的对立，具有深刻的社会批判意义：揭露了封建科举制度下儒林群丑可笑的喜剧表面背后悲剧性的本质。体现了作者对士人群体人格的反省与自觉（3分）。",
