   "essay": {
    "head": "四、论述题",
    "desc": "本大题共2小题，每小题14分，共28分。",
    "score": 14,
    "items": [
     {
      "q": "论述：试论苏轼诗歌的艺术特色。",
      "a": "（1）以文为诗，运用博喻。（4分）\n（2）有敏锐细致的观察力和出色的文字表现力，有才气。（2分）\n（3）以才学为诗，好议论、使事用典。将对事物的形象感受与哲理思考结合起来。（4分）\n（4）兼备各体而以七言为擅长，且风格多样。其七绝吐语清丽精美；七古气格雄健豪放。苏诗的基本风格有二：一是刚健含婀娜的清丽雄健，二是豪放加平淡的清旷闲逸。高风绝尘是其诗风的主导倾向。（4分）",
      "e": ""
     },
     {
      "q": "论述：试述《金瓶梅》的艺术成就。",
      "a": "（1）塑造人物摆脱了以往类型化的缺陷，既能突出人物性格的主要方面，又能在生活和人际关系中显示出性格的变化与复杂性。（4分）\n（2）以白描手法写世俗人情，直书其事，不加评论而是非美丑自现。（3分）\n（3）将各色人物交织在一起加以描写，突出人物之间的相互关系和作用，形成一种网状的艺术结构。（4分）\n（4）语言口语化、通俗化，人物语言则生动活泼，妙趣横生，富有个性。（3分）",
      "e": ""
     }
    ]
   }
