      "a": "（1）《西游记》最大的艺术特色在于它的奇幻色彩。小说以奇幻的艺术思维展现了一个光怪陆离、五彩缤纷的神话世界，读来令人精神飞跃，心旷神怡。（5分）\n（2）在艺术表现上，还有一个突出特点，是它幽默诙谐的色彩，寓庄于谐。（3分）\n（3）在艺术结构上采用单线发展的结构形式，除孙悟空作为主角贯穿全书外，每一回的故事具有相对独立的性质。（3分）\n（4）善于汲取民间说唱和方言口语的精华，采用民间谚语，形成轻松活泼、明快洗练的语言特点。（3分）",
      "e": ""
