     "q": "辛弃疾",
     "a": "辛词最突出的题材是抒发报国豪情和壮志难酬的悲愤。词体“本色”的婉媚中又透出\n刚毅之气，这是辛词所特有的风格。\n辛弃疾的词达到了词体艺术的高峰，形成了备受称道的“稼轩体”，对当时及后世均产\n生了深刻的影响。驰骋疆场杀敌立功，是稼轩一生的向往。壮志难酬、报国无门的愤懑成\n为稼轩词又一主题。喜议论，善用典是稼轩词的突出特点。\n前人论苏轼有“以诗为词”之说，论辛弃疾则有“以论为词”之评。\n出自辛弃疾《水龙吟》[登建康赏心亭]的诗句是倩何人、唤取红巾翠袖，揾英雄泪。（单选）"
