     "a": "散曲是用口语白话写成，直白地表露作者的内心感受或生活体验与追求。散曲的妙处\n不在耐人寻味，而在于一泻而下，一览无余，靠风趣、讽刺取胜。散曲生动活泼，通俗易\n懂，但又不乏文采，周德卿《中原音韵》概括其特点为“文而不文，俗而不俗”。"
