     "q": "清初词坛",
     "a": "（1）阳羡词派\n这一派成员有徐喈凤、万树、曹亮武、蒋景祁，陈维崧，以陈维崧成就最高。他们或\n是遗老逸民，或是忠烈后裔，因而词作多述民生之哀和故土之思，激荡楚郁，凄苍清狂。\n（2）浙西词派\n①以朱彝尊等为代表，因龚翔麟、朱彝尊、李良年、李符等及他本人的词作编为《浙\n西六家词》，人们遂把这一词派称作浙西词派。\n②浙西词派词风醇正秀雅，影响深远。作诗重“韵致”，讲醇雅章法，诗作空灵含蓄。\n（3）纳兰性德\n有《通志堂集》、《饮水词》等。工于诗词，尤为小令，爱情词低徊悠渺，婉丽清凄；\n边塞词寥廓苍远，绘景如画。\n朱彝尊《卖花声》［雨花台］一词的题材是吊古。（单选）\n纳兰性德的词集名是《饮水词》。（单选）\n陈维崧词的艺术特点（简答）：（1）少作以风华绮丽见称。中晚年作品深婉豪宕，苍凉\n沉郁。（2）慢词盘转起伏。骨力警拔，情致酣畅，将赋和歌行的手法运用于词。（3）以腾\n越飞扬的才情和劲挺的笔力写作小令，意境阔大。\n朱彝尊《江湖载酒集》的艺术特点（简答）：（1）《江湖载酒集》乃朱彝尊一生词创作\n的精粹所在。或沉郁花凉，或清新流动。（2）其吊古之作，将故国之思化为空灵的意绪，\n营造种感伤的氛围，其情爱词高秀圆转或凄丽缠绵。"
